import { type IoFileExport, ioGvlExportOf } from "./io-gvl-export.ts";
import type { IoState } from "./io-state.ts";

// Display logic of the "Export CSV" action (ADR 0049 amendment of 2026-10-20).
// It follows the rule of the GVL export: the core decides whether a CSV exists,
// the viewer only avoids a request known to be refused (409). The file itself
// is generated by the core.

export function ioCsvExportOf(state: IoState): IoFileExport {
  const { enabled } = ioGvlExportOf(state);
  return { enabled, titleKey: enabled ? "io.csv.title" : "io.csv.unavailable" };
}
